PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(xsd:decimal(?scenarioChange)) AS ?scenario_change) ?rebalance_logic
WHERE {
  ?investor a wm:Investor .
  ?rebalancingAction a wm:RebalancingAction ;
    wm:rebalancingActionOfInvestor ?investor ;
    wm:logic ?rebalance_logic .
  ?scenarioRebalancing a wm:ScenarioRebalancing ;
    wm:scenarioRebalancingOfInvestor ?investor ;
    wm:newAllocationPct ?scenarioNewAllocationPct ;
    wm:currentAllocationPct ?scenarioCurrentAllocationPct .
  BIND(xsd:decimal(?scenarioNewAllocationPct) - xsd:decimal(?scenarioCurrentAllocationPct) AS ?scenarioChange)
}
GROUP BY ?rebalance_logic

