PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category (AVG(xsd:decimal(?rebalancing_amount)) AS ?avg_rebalancing_amount) (AVG(xsd:decimal(?cash_flow)) AS ?avg_cash_flow) (AVG(xsd:decimal(?goal_progress)) AS ?avg_goal_progress) (AVG(xsd:decimal(?shortfall)) AS ?avg_shortfall)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:category ?category .

  # Rebalancing Amount
  OPTIONAL {
    ?investor wm:hasRebalancingAction ?rebalancingAction .
    ?rebalancingAction wm:amount ?rebalancing_amount .
  }

  # Cash Flow
  OPTIONAL {
    ?investor wm:hasCashFlow ?cashFlow .
    ?cashFlow wm:amount ?cash_flow .
  }

  # Goal Progress
  OPTIONAL {
    ?investor wm:hasInvestmentGoal ?investmentGoal .
    ?investmentGoal wm:progressPct ?goal_progress .
  }

  # Shortfall
  OPTIONAL {
    ?investor wm:hasInvestmentGoal ?investmentGoal .
    ?investmentGoal wm:shortfall ?shortfall .
  }
}
GROUP BY ?category

