  FILTER NOT EXISTS { ?holding wm:sector ?sector . FILTER (isBlank(?sector)) }
  FILTER NOT EXISTS { ?holding wm:segment ?segment . FILTER (isBlank(?segment)) }
  FILTER NOT EXISTS { ?holding wm:category ?category . FILTER (isBlank(?category)) }
