  (COUNT(DISTINCT ?investorId) AS ?missing_hasSegment)
  (COUNT(DISTINCT ?investorId) AS ?missing_focusesOnSector)
  (COUNT(DISTINCT ?investorId) AS ?missing_category)
  (COUNT(DISTINCT ?investorId) AS ?missing_hasPortfolioHealth)
  (COUNT(DISTINCT ?investorId) AS ?missing_hasSectorAllocation)
  (COUNT(DISTINCT ?investorId) AS ?missing_hasRebalancingAction)
  (COUNT(DISTINCT ?investorId) AS ?missing_timeHorizon)
