  (COUNT(DISTINCT ?investorId) AS ?missing_hasRiskTolerance)
  (COUNT(DISTINCT ?investorId) AS ?missing_hasScenarioRebalancing)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  FILTER NOT EXISTS { ?investor wm:segment ?segment . }
  FILTER NOT EXISTS { ?investor wm:hasSegment ?hasSegment . }
  FILTER NOT EXISTS { ?investor wm:focusesOnSector ?focusesOnSector . }
  FILTER NOT EXISTS { ?investor wm:category ?category . }
  FILTER NOT EXISTS { ?investor wm:hasPortfolioHealth ?hasPortfolioHealth . }
  FILTER NOT EXISTS { ?investor wm:hasSectorAllocation ?hasSectorAllocation . }
  FILTER NOT EXISTS { ?investor wm:hasRebalancingAction ?hasRebalancingAction . }
  FILTER NOT EXISTS { ?investor wm:timeHorizon ?timeHorizon . }
  FILTER NOT EXISTS { ?investor wm:hasInvestmentGoal ?hasInvestmentGoal . }
  FILTER NOT EXISTS { ?investor wm:investmentGoal ?investmentGoal . }
  FILTER NOT EXISTS { ?investor wm:riskTolerance ?riskTolerance . }
  FILTER NOT EXISTS { ?investor wm:hasTimeHorizon ?hasTimeHorizon . }
  FILTER NOT EXISTS { ?investor wm:hasInvestmentGoalType ?hasInvestmentGoalType . }
  FILTER NOT EXISTS { ?investor wm:hasCashFlow ?hasCashFlow . }
  FILTER NOT EXISTS { ?investor wm:hasHolding ?hasHolding . }
  FILTER NOT EXISTS { ?investor wm:hasCategory ?hasCategory . }
  FILTER NOT EXISTS { ?investor wm:hasRiskTolerance ?hasRiskTolerance . }
  FILTER NOT EXISTS { ?investor wm:hasScenarioRebalancing ?hasScenarioRebalancing . }
}
